/**
 * In-memory private and catalog storage that counts its writes; a lost PUT stores nothing until `land()`, `failDelete` fails before
 * deleting and `failDeleteAfter` loses the acknowledgement of a delete that happened. `beforePut` runs once before the next PUT.
 */
class Storage implements ImportObjectStorage {
    objects = new Map<string, ImportObjectIdentity>(); puts = 0; copies = 0; deletes = 0; failDelete = false; failDeleteAfter = false; loseNextPut = false; private lost: string | null = null;
    beforePut?: () => Promise<unknown>;
    private path = (target: ImportObjectTarget) => `${target.bucket}/${target.key}`;
    async head(target: ImportObjectTarget) { return this.objects.get(this.path(target)) ?? null; }
    async put(target: ImportObjectTarget) {
        const hook = this.beforePut; this.beforePut = undefined; await hook?.();
        this.puts++;
        if (this.loseNextPut) { this.loseNextPut = false; this.lost = this.path(target); throw new Error('acknowledgement lost'); }
        const identity = { etag: `"${target.operationId}"`, versionId: 'stage-version' }; this.objects.set(this.path(target), identity); return identity;
    }
    /** The PUT whose acknowledgement was lost lands after all. */
    land() { if (this.lost) this.objects.set(this.lost, { etag: '"late-etag"', versionId: 'late-version' }); this.lost = null; }
    async copy(_source: ImportObjectTarget & ImportObjectIdentity, target: ImportObjectTarget) { this.copies++; const identity = { etag: '"canonical-etag"', versionId: 'canonical-version' }; this.objects.set(this.path(target), identity); return identity; }
    async delete(target: ImportObjectTarget & ImportObjectIdentity) {
        this.deletes++; if (this.failDelete) throw new Error('cleanup failed');
        this.objects.delete(this.path(target)); if (this.failDeleteAfter) throw new Error('cleanup acknowledgement lost');
    }
    has(asset: ImportAsset) { return this.objects.has(`${asset.bucket}/${asset.key}`); }
}

