test('the publication lock keeps the cover in use; completion publishes it as the Album cover, keeps it and cleans every other lookup cover', async () => {
    const id = await chosen(1), storage = new Storage();
    await pass(storage, id, artwork(chain(1)).client);
    // An older lookup cover no longer applied, which no pass has cleaned yet, is kept while approval locks the project.
    const old = { slotId: slotOf(9), operationId: randomUUID(), actorId: by, bucket: PRIVATE, key: `imports/${id}/${slotOf(9)}/x`, sha256: '9'.repeat(64), byteLength: 10, contentType: 'image/jpeg',
        filename: 'cover-art-archive-front.jpg', state: 'ready' as const, versionId: 'v', etag: '"e"', updatedAt: new Date(), leaseOwner: null, leaseUntil: null, transferDeadline: null,
        failureConfirmedAt: null, duration: null, format: null, representation: null, tags: null, recovery: { operationId: randomUUID(), expectedRevision: 1, kind: 'upload' as const, actorId: by } };
    await projects().updateOne({ _id: new ObjectId(id) }, { $push: { 'media.assets': old }, $set: { 'media.lookupCover.due': true } });
    storage.objects.set(`${PRIVATE}/${old.key}`, { etag: '"e"', versionId: 'v' });
    assert.equal((await approve(id)).item.publication, 'preparing');
    assert.equal((await stored(id)).media!.publication!.cover?.slotId, slotOf(1));
    await pass(storage, id, artwork([]).client);
    let doc = await stored(id);
    assert.deepEqual([lookupAsset(doc, 1)?.state, lookupAsset(doc, 9)?.state, doc.media!.lookupCover!.due, storage.deletes], ['ready', 'ready', true, 0]);
    await assert.rejects(cleanupAdminImportAsset(by, id, slotOf(1), { operationId: randomUUID(), expectedRevision: doc.revision }, storage), code('ADMIN_IMPORT_PUBLICATION_LOCKED'));
    assert.equal(await runAdminImportPublicationOnce(storage, id), true);
    doc = await stored(id);
    assert.equal(doc.media!.publication!.state, 'complete');
    // The published cover stays; the completion sweep cleaned the other lookup cover; nothing outside the import names an artwork host.
    assert.deepEqual([lookupAsset(doc, 1)?.state, doc.media!.assets.find(asset => asset.slotId === slotOf(9))?.state], ['ready', 'deleted']);
    const album = await getDb()!.collection('albums').findOne({ _id: new ObjectId(doc.media!.publication!.albumId) });
    assert.equal(typeof album?.coverArtId, 'string'); assert.equal(album!.coverArtUrl, `/content/images/${album!.coverArtId}`);
    const image = await getDb()!.collection('imageAssets').findOne({ _id: new ObjectId(album!.coverArtId) });
    assert.deepEqual([image?.ownerType, image?.originalFileName, image?.contentType, image?.uploadStatus], ['album', 'cover-art-archive-front.jpg', 'image/jpeg', 'ready']);
    for (const name of ['albums', 'audioTracks', 'artists', 'organizations', 'imageAssets']) {
        assert.equal(JSON.stringify(await getDb()!.collection(name).find({}).toArray()).match(/coverartarchive\.org|archive\.org/), null, name);
    }
    // A completed project is no longer staged: the next pass (an hour later, as the lock asked) ends the due job without work.
    assert.equal(await pass(storage, id, artwork([]).client, { now: later(2 * 3600_000) }), true);
    assert.equal((await stored(id)).media!.lookupCover!.due, false);
});

